# Get all PCI-based USB controllers
 $usbControllers = Get-CimInstance Win32_USBController | Where-Object { $_.PNPDeviceID -like "PCI\VEN_*" } | Select-Object -ExpandProperty PNPDeviceID

 foreach ($usb in $usbControllers) {
  $msiKey = "HKLM:\SYSTEM\CurrentControlSet\Enum\$usb\Device Parameters\Interrupt Management\MessageSignaledInterruptProperties"
  if (Test-Path $msiKey) {
  Set-ItemProperty -Path $msiKey -Name "MSISupported" -Value 1
  }

  $affinityKey = "HKLM:\SYSTEM\CurrentControlSet\Enum\$usb\Device Parameters\Interrupt Management\Affinity Policy"
  if (Test-Path $affinityKey) {
  Set-ItemProperty -Path $affinityKey -Name "DevicePriority" -Value 0
  }
 }

